 explicit EngineRecording(Session& owner){auto& s=session;s.device=owner.device;s.queue=owner.queue;s.output=owner.output;check(SUCCEEDED(s.device->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&s.fence))),"engine-fence");s.event=CreateEventW(nullptr,FALSE,FALSE,nullptr);check(s.event&&s.commandCreate(),"engine-private-recording");}
