 void fill(unsigned kind,unsigned frame,unsigned format){unsigned char* p{};D3D12_RANGE empty{};check(SUCCEEDED(resource->Map(0,&empty,reinterpret_cast<void**>(&p))),"map-upload");
  for(unsigned y=0;y<footprint.Footprint.Height;++y)for(unsigned x=0;x<footprint.Footprint.Width;++x){auto row=p+footprint.Offset+uint64_t(y)*footprint.Footprint.RowPitch;
   if(kind==1)reinterpret_cast<float*>(row)[x]=.5f;
   else if(kind==2){auto pixel=reinterpret_cast<uint16_t*>(row)+2*x;pixel[0]=footprint.Footprint.Width==640?0xc400:0xc800;pixel[1]=0;}
   else{bool stripe=((x+footprint.Footprint.Width-frame*8)%footprint.Footprint.Width/24)%2!=0;
    if(format==28){auto pixel=row+4*x;pixel[0]=stripe?192:64;pixel[1]=y<footprint.Footprint.Height/2?128:64;pixel[2]=128;pixel[3]=255;}
    else reinterpret_cast<uint32_t*>(row)[x]=(stripe?768u:256u)|((y<footprint.Footprint.Height/2?512u:256u)<<10)|(512u<<20)|(3u<<30);
   }}resource->Unmap(0,nullptr);}
