  D3D12_TEXTURE_COPY_LOCATION to{},from{};to.pResource=resource;to.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;to.PlacedFootprint=footprint;from.pResource=source;from.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
  s.command->CopyTextureRegion(&to,0,0,0,&from,nullptr);transition(s.command,source,D3D12_RESOURCE_STATE_COPY_SOURCE,before);check(s.submit(),"read-submit");
  unsigned char* p{};D3D12_RANGE range{0,size_t(bytes)};check(SUCCEEDED(resource->Map(0,&range,reinterpret_cast<void**>(&p))),"read-map");uint64_t hash=14695981039346656037ull;unsigned low=1024,high=0;
  for(unsigned y=0;y<footprint.Footprint.Height;++y)for(unsigned x=0;x<footprint.Footprint.Width;++x){auto row=p+footprint.Offset+uint64_t(y)*footprint.Footprint.RowPitch;auto value=reinterpret_cast<uint32_t*>(row)[x];unsigned red=format==28?value&255u:value&1023u;low=std::min(low,red);high=std::max(high,red);hash=(hash^value)*1099511628211ull;}
