uint32_t patternPixel(unsigned x,unsigned y,unsigned frame,unsigned format){bool stripe=((x+1280-frame*8)%1280/24)%2!=0;return format==28?((stripe?192u:64u)|((y<360?128u:64u)<<8)|(128u<<16)|(255u<<24)):((stripe?768u:256u)|((y<360?512u:256u)<<10)|(512u<<20)|(3u<<30));}
