  for(auto& r:dirty){D3D12_BOX box{UINT(r.left),UINT(r.top),0,UINT(r.right),UINT(r.bottom),1};s.command->CopyTextureRegion(&to,r.left,r.top,0,&from,&box);}transition(s.command,virtualBuffer,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_PRESENT);check(s.submit(),"partial-submit");
